import sys
import hashlib
import argparse
from xml.etree import ElementTree as ET

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    users = []
    for user_elem in root.findall('user'):
        users.append({
            'name': user_elem.get('name'),
            'role': user_elem.get('role'),
            'hash': user_elem.get('hash'),
            'token_digest': user_elem.get('token_digest')
        })
    return users

def compute_digest(token, hash_type):
    if hash_type == 'sha1':
        return hashlib.sha1(token.encode()).hexdigest()
    elif hash_type == 'sha256':
        return hashlib.sha256(token.encode()).hexdigest()
    elif hash_type == 'md5':
        return hashlib.md5(token.encode()).hexdigest()
    else:
        return token  # fallback, though unlikely per problem description

def process_requests(users):
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        token, method, path = line.split(maxsplit=2)
        for user in users:
            computed_digest = compute_digest(token, user['hash'])
            if computed_digest == user['token_digest']:
                if user['role'] == 'admin':
                    print(f"ALLOW {user['name']}")
                    break
                elif user['role'] == 'viewer' and method == 'GET' and path.startswith('/public/'):
                    print(f"ALLOW {user['name']}")
                    break
        else:
            print("DENY")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config', help='Path to XML configuration file')
    args = parser.parse_args()
    users = parse_xml(args.config)
    process_requests(users)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import hashlib
import argparse

def parse_xml_config(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    hash_algorithm = root.attrib.get('hash')
    users = []
    for user_elem in root.findall('user'):
        name = user_elem.attrib.get('name')
        role = user_elem.attrib.get('role')
        token_digest = user_elem.attrib.get('token_digest')
        users.append((name, role, token_digest))
    return hash_algorithm, users

def verify_token(token, hash_algorithm, token_digest):
    if not token_digest:
        return None
    computed_digest = hashlib.new(hash_algorithm, token.encode('utf-8')).hexdigest()
    return computed_digest == token_digest

def process_input(hash_algorithm, users):
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        token, method, path = line.split(maxsplit=2)
        for name, role, token_digest in users:
            if verify_token(token, hash_algorithm, token_digest):
                if role == 'admin':
                    print(f"ALLOW {name}")
                    break
                elif role == 'viewer' and method == 'GET' and path.startswith('/public/'):
                    print(f"ALLOW {name}")
                    break
        else:
            print("DENY")

def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('config_path', type=str)
    args = parser.parse_args()
    hash_algorithm, users = parse_xml_config(args.config_path)
    process_input(hash_algorithm, users)

if __name__ == "__main__":
    main()
